public class Solution {
    private static BufferedReader reader;
    private static PrintWriter writer;
    private static StringTokenizer tokenizer;

    public void solve() {
        int n = readInt();
        int m = readInt();

        if (m == 1) {
            write(n - 1);
        } else {
            write(1L * n * (m - 1));
        }
    }

    public static void main(String[] args) {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        try {
            new Solution().solve();
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            writer.flush();
            writer.close();
            try {
                reader.close();
            } catch (IOException e) {
                // ignore
            }
        }
    }

    private static String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public static int readInt() {
        return Integer.parseInt(nextToken());
    }

    public static long readLong() {
        return Long.parseLong(nextToken());
    }

    public static double readDouble() {
        return Double.parseDouble(nextToken());
    }

    public static int[] readIntArray() {
        int n = readInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = readInt();
        }
        return arr;
    }

    public static long[] readLongArray() {
        int n = readInt();
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = readLong();
        }
        return arr;
    }

    public static double[] readDoubleArray() {
        int n = readInt();
        double[] arr = new double[n];
        for (int i = 0; i < n; i++) {
            arr[i] = readDouble();
        }
        return arr;
    }

    public static int[][] readIntMatrix(int numberOfRows) {
        int[][] matrix = new int[numberOfRows][];
        for (int i = 0; i < numberOfRows; i++) {
            matrix[i] = readIntArray();
        }
        return matrix;
    }

    public static int[][] readAndTransposeIntMatrix(int numberOfRows) {
        int[][] matrix = readIntMatrix(numberOfRows);
        int cols = matrix[0].length;
        int[][] ret = new int[cols][numberOfRows];
        for (int i = 0; i < cols; i++) {
            for (int j = 0; j < numberOfRows; j++) {
                ret[i][j] = matrix[j][i];
            }
        }
        return ret;
    }

    public static String[] readLines(int quantity) {
        String[] lines = new String[quantity];
        for (int i = 0; i < quantity; i++) {
            try {
                lines[i] = reader.readLine().trim();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return lines;
    }

    public static void writeArray(List<?> array) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < array.size(); i++) {
            if (i > 0) sb.append(" ");
            sb.append(array.get(i));
        }
        writer.println(sb.toString());
    }

    public static void write(Object... array) {
        writeArray(Arrays.asList(array));
    }

    public static void writeLines(List<?> array) {
        for (Object o : array) {
            writer.println(o);
        }
    }

    private static <T> T[] init(int size) {
        @SuppressWarnings("unchecked")
        T[] ret = (T[]) new Object[size];
        return ret;
    }
}

